#!/usr/bin/env node
// Inlines the SQL migrations generated by drizzle-kit (drizzle/*.sql) into a
// TypeScript module, so the app can bundle them without a Metro/Babel plugin
// for .sql files, and tests can run the exact same migrations in Node.
// Run via `npm run db:generate`; a test fails if the output is stale.
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const drizzleDir = path.join(root, 'drizzle');
const outFile = path.join(root, 'src', 'data', 'migrations.generated.ts');

function render() {
  const journal = JSON.parse(fs.readFileSync(path.join(drizzleDir, 'meta', '_journal.json'), 'utf8'));
  const migrations = {};
  for (const entry of journal.entries) {
    const key = `m${String(entry.idx).padStart(4, '0')}`;
    migrations[key] = fs.readFileSync(path.join(drizzleDir, `${entry.tag}.sql`), 'utf8');
  }
  return (
    '// Generated by scripts/bundle-migrations.js from drizzle/. Do not edit.\n' +
    `const journal = ${JSON.stringify({ entries: journal.entries }, null, 2)};\n\n` +
    `const migrations: Record<string, string> = ${JSON.stringify(migrations, null, 2)};\n\n` +
    'export default { journal, migrations };\n'
  );
}

module.exports = { render, outFile };

if (require.main === module) {
  fs.writeFileSync(outFile, render());
  console.log(`Wrote ${path.relative(root, outFile)}`);
}
